@pragma('vm:entry-point')
Map<String, int> aggregateBranchStock(Map<String, int> mainStock, int levels) {
  if (levels <= 0 || mainStock.isEmpty) return {};
  if (levels == 1) return Map<String, int>.from(mainStock);
  Map<String, int> result = {};
  mainStock.forEach((key, value) {
    result[key] = value * levels;
  });
  Map<String, int> sub = aggregateBranchStock(mainStock, levels - 1);
  sub.forEach((k, v) {
    result[k] = (result[k] ?? 0) + v;
  });
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(aggregateBranchStock({'item1': 5}, 1).toString() == '{item1: 5}');
  assert(aggregateBranchStock({'item1': 5}, 2).toString() == '{item1: 15}');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = aggregateBranchStock;

  expect(candidate({'a': 10}, 1), {'a': 10});
  expect(candidate({'a': 10}, 2), {'a': 30});
  expect(candidate({'a': 10, 'b': 4}, 2), {'a': 30, 'b': 12});
  expect(candidate({}, 3), {});
  expect(candidate({'x': 2}, 0), {});
  expect(candidate({'m': 1, 'n': 1}, 4), {'m': 10, 'n': 10});
}

