bool canTradeInEqualStacks(int playerAItems, int playerBItems) {
  if (playerAItems < 1 || playerBItems < 1) return false;
  int a = playerAItems;
  int b = playerBItems;
  while (b != 0) {
    final temp = b;
    b = a % b;
    a = temp;
  }
  return a > 1;
}

