@pragma('vm:entry-point')
String dominantAsciiRow(List<String> rows) {
  if (rows.isEmpty) return 'empty';
  final counts = <String, int>{};
  String? bestRow;
  var bestCount = 0;
  for (final row in rows) {
    final c = (counts[row] ?? 0) + 1;
    counts[row] = c;
    if (c > bestCount || (c == bestCount && (bestRow == null || row.compareTo(bestRow) < 0))) {
      bestRow = row;
      bestCount = c;
    }
  }
  return '$bestRow|$bestCount';
}

@pragma('vm:entry-point')
void main() {
  assert(dominantAsciiRow([]) == 'empty');
  assert(dominantAsciiRow(['####']) == '####|1');
  assert(dominantAsciiRow(['+---+', '|...|', '+---+', '|...|', '+---+']) == '+---+|3');
  print('All tests passed!');
}

tests:
void main() {
  final candidate = dominantAsciiRow;

  expect(candidate([]), 'empty');
