String wifiSignalDescription(int bins) {
  int b = bins & 0xF;
  if (b == 0) return "no signal";
  int count = 0;
  int temp = b;
  while (temp > 0) {
    count += temp & 1;
    temp >>= 1;
  }
  if (count >= 3) return "variable";
  List<String> active = [];
  if ((b & 1) != 0) active.add("excellent");
  if ((b & 2) != 0) active.add("good");
  if ((b & 4) != 0) active.add("fair");
  if ((b & 8) != 0) active.add("poor");
  return active.join("+");
}

