List<int> coprimeCardValues(int cardValue) {
  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }
  List<int> result = [];
  for (int i = 1; i <= 13; i++) {
    if (gcd(cardValue, i) == 1) {
      result.add(i);
    }
  }
  return result;
}

