int findHighestMetRuleIndex(List<int> sortedMinLengths, int passwordLength) {
  int left = 0;
  int right = sortedMinLengths.length - 1;
  int result = -1;
  while (left <= right) {
    int mid = left + ((right - left) >> 1);
    if (sortedMinLengths[mid] <= passwordLength) {
      result = mid;
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }
  return result;
}

