bool canBuildExactPlaylist(List<int> songDurations, int targetMinutes) {
  if (targetMinutes == 0) return true;
  List<bool> dp = List.filled(targetMinutes + 1, false);
  dp[0] = true;
  for (int song in songDurations) {
    for (int j = targetMinutes; j >= song; j--) {
      if (dp[j - song]) {
        dp[j] = true;
      }
    }
  }
  return dp[targetMinutes];
}

