List<int> cumulativeEditCounts(List<int> distances) {
  if (distances.isEmpty) return [];
  int maxDist = distances.reduce((a, b) => a > b ? a : b);
  List<int> counts = List.filled(maxDist, 0);
  for (int d in distances) {
    counts[d - 1] += 1;
  }
  int cumulative = 0;
  for (int i = 0; i < counts.length; i++) {
    cumulative += counts[i];
    counts[i] = cumulative;
  }
  return counts;
}

