int calculateRestockNeeds(int currentStockMask, int requiredItemsMask) {
  int missing = requiredItemsMask & ~currentStockMask;
  int needs = 0;
  int temp = missing;
  for (int i = 0; i < 16; i++) {
    if ((temp & 1) != 0) {
      if (i < 8) {
        needs += 2;
      } else {
        if ((i % 2) == 0) {
          needs += 3;
        } else {
