List<int> findMoistureSegments(List<int> levels, int minMoisture) {
  List<int> result = [];
  int n = levels.length;
  int start = 0;
  while (start < n) {
    if (levels[start] >= minMoisture) {
      int end = start;
      while (end < n && levels[end] >= minMoisture) {
        end++;
      }
      result.add(end - start);
      start = end;
    } else {
      start++;
    }
  }
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(findMoistureSegments([5, 6, 7, 3, 8], 5).toString() == '[3, 1]');
  assert(findMoistureSegments([], 5).toString() == '[]');
  print('All tests passed!');
}

