int decodeManifestUnits(String manifest) {
  int total = 0;
  int current = 0;

  for (int i = 0; i < manifest.length; i++) {
    int? digit = int.tryParse(manifest[i]);

    if (digit != null) {
      current = current * 10 + digit;
    } else if (current > 0) {
      total += current;
      current = 0;
    }
  }

  return total + current;
}

