bool isPremiumSeat(int seatNumber, int rowCapacity) {
  if (seatNumber <= 0 || rowCapacity <= 0) return false;
  int a = seatNumber;
  int b = rowCapacity;
  while (b != 0) {
    int temp = b;
    b = a % b;
    a = temp;
