List<int> resolveElevatorStops(List<Object> requests) {
  List<int> result = [];
  for (Object request in requests) {
    if (request is int) {
      result.add(request);
    } else if (request is List<Object>) {
      int groupFloor = request[0] as int;
      List<Object> prerequisites = request.sublist(1);
      result.addAll(resolveElevatorStops(prerequisites));
      result.add(groupFloor);
