@pragma('vm:entry-point')
List<int> smoothThermostatSchedule(List<int> preferred) {
  if (preferred.isEmpty) return [];
  List<int> result = [preferred[0]];
  for (int i = 1; i < preferred.length; i++) {
    int prev = result[i - 1];
    int curr = preferred[i];
    if ((curr - prev).abs() > 2) {
      curr = prev + 2 * (curr > prev ? 1 : -1);
    }
    result.add(curr);
  }
  return result;
}

