int countGreenIntersectionsAtTime(List<List<int>> greenPhaseGrid, int time) {
  int count = 0;
  for (final row in greenPhaseGrid) {
    for (final phase in row) {
      final cycle = 2 * phase + 3;
      if (time % cycle < phase) {
        count++;
