@pragma('vm:entry-point')
String computeTelemetryDigest(List<int> samples) {
  if (samples.isEmpty) return "";
  if (samples.length == 1) return samples[0].toString();
  int mid = samples.length ~/ 2;
  String left = computeTelemetryDigest(samples.sublist(0, mid));
  String right = computeTelemetryDigest(samples.sublist(mid));
  return "($left|$right)";
}

@pragma('vm:entry-point')
