@pragma('vm:entry-point')
String longestSortedShelfRun(List<String> codes) {
  if (codes.isEmpty) return '';
  int bestLen = 1;
  int bestEnd = 0;
  int cur = 1;
  for (int i = 1; i < codes.length; i++) {
    cur = codes[i].compareTo(codes[i - 1]) >= 0 ? cur + 1 : 1;
    if (cur > bestLen) {
      bestLen = cur;
      bestEnd = i;
    }
  }
  return codes.sublist(bestEnd - bestLen + 1, bestEnd + 1).join('-');
}

