List<String> scanBracketMatchIdentifiers(String input) {
  List<String> matches = [];
  String? letter;
  for (int i = 0; i < input.length; i++) {
    int code = input.codeUnitAt(i);
    if (code >= 65 && code <= 90) {
      letter = String.fromCharCode(code);
    } else if (code >= 48 && code <= 57 && letter != null) {
      matches.add(letter! + String.fromCharCode(code));
      letter = null;
    } else {
      letter = null;
    }
  }
  return matches;
}

