double nextTrainDeparture(List<int> timetable, int queryMinute) {
  int left = 0;
  int right = timetable.length;
  while (left < right) {
    int mid = left + (right - left) >> 1;
    if (timetable[mid] < queryMinute) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  if (left == timetable.length) return -1.0;
  return timetable[left].toDouble();
}

