Set<int> findCorruptTelemetryIndices(List<int> samples) {
  final corrupt = <int>{};
  for (var i = 0; i < samples.length; i++) {
    final packet = samples[i] & 0x1FF;
    var count = 0;
    for (var bits = packet; bits != 0; bits &= bits - 1) {
