List<int> parseLedgerAmounts(String entries) {
  List<int> amounts = [];
  int i = 0;
  while (i < entries.length) {
    int sign = entries[i] == 'C' ? 1 : -1;
    i++;
    int value = 0;
    while (i < entries.length && entries.codeUnitAt(i) >= 48 && entries.codeUnitAt(i) <= 57) {
      value = value * 10 + (entries.codeUnitAt(i) - 48);
      i++;
    }
    amounts.add(sign * value);
  }
  return amounts;
}

