String checkPasswordPrimeSum(String password) {
  int sum = 0;
  for (int i = 0; i < password.length; i++) {
    int code = password.codeUnitAt(i);
    if (code >= 48 && code <= 57) {
      sum += code - 48;
    }
  }
  if (sum < 2) return "Invalid";
  for (int i = 2; i * i <= sum; i++) {
