List<String> extractBracketedTags(String logLine) {
  final tags = <String>[];
  final buffer = StringBuffer();
  var inside = false;
  for (var i = 0; i < logLine.length; i++) {
    final ch = logLine[i];
    if (ch == '[') {
      inside = true;
      buffer.clear();
    } else if (ch == ']') {
      if (inside) {
        tags.add(buffer.toString());
        inside = false;
      }
    } else if (inside) {
      buffer.write(ch);
    }
  }
  return tags;
}

