bool hasSignalOfDuration(List<int> sortedDurations, int target) {
  // Morse operators log each transmitted symbol's duration in time units.
  // Given the log sorted ascending, binary-search for an exact duration.
  int lo = 0;
  int hi = sortedDurations.length - 1;
  while (lo <= hi) {
    int mid = (lo + hi) ~/ 2;
    if (sortedDurations[mid] == target) return true;
    if (sortedDurations[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return false;
}

