@pragma('vm:entry-point')
int minTransmissionOverhead(List<int> packetSizes) {
  int n = packetSizes.length;
  if (n == 0) return 0;
  List<int> dp = List.filled(n + 1, 1000000);
  dp[0] = 0;
  for (int i = 1; i <= n; i++) {
    int sum = 0;
    for (int j = i; j >= 1; j--) {
      sum += packetSizes[j - 1];
      if (sum > 100) break;
      int cost = dp[j - 1] + sum + 8;
      dp[i] = dp[i] < cost ? dp[i] : cost;
    }
  }
  return dp[n];
}

@pragma('vm:entry-point')
void main() {
  assert(minTransmissionOverhead([]) == 0);
  assert(minTransmissionOverhead([30]) == 38);
