Set<int> extractRepeatFloors(List<int> requests, int streakLength) {
  Set<int> result = {};
  if (streakLength <= 0 || requests.isEmpty) return result;
  int left = 0;
  for (int right = 0; right < requests.length; right++) {
    if (requests[right] != requests[left]) {
      left = right;
    }
    if (right - left + 1 >= streakLength) {
      result.add(requests[left]);
    }
  }
  return result;
}

