@pragma('vm:entry-point')
double firstPrecinctReachingThreshold(List<int> cumulativeVotes, int threshold) {
  if (cumulativeVotes.isEmpty || cumulativeVotes.last < threshold) return -1.0;
  int low = 0, high = cumulativeVotes.length - 1;
  while (low < high) {
    int mid = (low + high) ~/ 2;
    if (cumulativeVotes[mid] >= threshold) {
      high = mid;
    } else {
      low = mid + 1;
    }
  }
  return (low + 1).toDouble();
}

@pragma('vm:entry-point')
