@pragma('vm:entry-point')
Set<int> elevatorVisitedFloors(List<int> requests) {
  Set<int> visited = {0};
  int current = 0;
  bool acceptUp = true;
  for (int req in requests) {
    if (req > current && acceptUp) {
      current = req;
      visited.add(current);
    } else if (req < current && !acceptUp) {
      current = req;
      visited.add(current);
    } else if (req != current) {
      acceptUp = req > current;
    }
  }
  return visited;
}

