List<String> findRowsWithExactBookings(List<String> seats, int targetCount) {
  Map<String, Set<String>> rowBookings = {};
  for (String seat in seats) {
    if (seat.isEmpty) continue;
    String row = seat[0];
    rowBookings.putIfAbsent(row, () => <String>{}).add(seat);
  }
  return rowBookings.entries
      .where((e) => e.value.length == targetCount)
      .map((e) => e.key)
      .toList()
    ..sort();
}

