int getTournamentRank(List<int> scores, int playerIndex) {
  if (scores.isEmpty || playerIndex < 0 || playerIndex >= scores.length) {
    return -1;
  }
  int rank = 0;
  for (int i = 0; i < scores.length; i++) {
    if (scores[i] > scores[playerIndex]) {
      rank++;
    } else if (scores[i] == scores[playerIndex] && i < playerIndex) {
      rank++;
    }
  }
  return rank;
