int countComplementaryDnaPairs(String dna) {
  final Map<String, String> complement = {'A': 'T', 'T': 'A', 'C': 'G', 'G': 'C'};
  final List<String> stack = [];
  int pairs = 0;
  for (int i = 0; i < dna.length; i++) {
    final String base = dna[i];
    if (stack.isNotEmpty && complement[stack.last] == base) {
      stack.removeLast();
      pairs++;
    } else {
      stack.add(base);
    }
  }
  return pairs;
}

