bool hasStableTelemetryRows(List<List<int>> samples, int maxJump) {
  for (int r = 0; r < samples.length; r++) {
    List<int> row = samples[r];
    for (int c = 1; c < row.length; c++) {
      int diff = row[c] - row[c - 1];
      if (diff < 0) {
        diff = -diff;
      }
      if (diff > maxJump) {
        return false;
      }
    }
  }
  return true;
}

