String playlistEndLabel(int startDay, int startSecondsIntoDay, int totalDurationSeconds) {
  const int secondsPerDay = 86400;
  int totalSeconds = startSecondsIntoDay + totalDurationSeconds;
  int endDay = startDay + (totalSeconds ~/ secondsPerDay);
  int endSeconds = totalSeconds % secondsPerDay;
  int hours = endSeconds ~/ 3600;
  int minutes = (endSeconds % 3600) ~/ 60;
  String hh = hours.toString().padLeft(2, '0');
  String mm = minutes.toString().padLeft(2, '0');
