List<String> convertElevatorFloorsToOctal(List<int> requestedFloors) {
  List<String> stops = [];
  for (int floor in requestedFloors) {
    int n = floor.abs();
    String octal = n == 0 ? '0' : '';
    while (n > 0) {
      octal = (n % 8).toString() + octal;
      n = n ~/ 8;
    }
    stops.add(floor < 0 ? 'Floor -$octal' : 'Floor $octal');
  }
  return stops;
}

