String dnaComplementDivide(String dna) {
  if (dna.length <= 1) {
    return _complementChar(dna);
  }
  int mid = dna.length ~/ 2;
  String left = dnaComplementDivide(dna.substring(0, mid));
  String right = dnaComplementDivide(dna.substring(mid));
  return left + right;
}

String _complementChar(String c) {
  switch (c) {
    case 'A': return 'T';
    case 'T': return 'A';
    case 'C': return 'G';
    case 'G': return 'C';
    default: return '';
  }
}

