double barcodeScanPosition(List<int> sortedDigits, int target) {
  int lo = 0;
  int hi = sortedDigits.length;
  while (lo < hi) {
    int mid = lo + (hi - lo) ~/ 2;
    if (sortedDigits[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid;
    }
  }
  return lo.toDouble();
}

