@pragma('vm:entry-point')
List<int> scheduleDiceRounds(int startDay, int gapDays, int numRounds) {
  // Rounds of the dice game are played starting on day index startDay,
  // with gapDays days between scheduled rounds. Day indices that are
  // multiples of 7 are rest days: a round landing there is pushed to the
  // next day. The next round is scheduled gapDays after the actual play day.
  List<int> playDays = [];
  int day = startDay;
  for (int i = 0; i < numRounds; i++) {
    if (day % 7 == 0) {
      day += 1;
    }
    playDays.add(day);
    day += gapDays;
  }
  return playDays;
}

