@pragma('vm:entry-point')
List<String> summarizeServerLogs(List<String> logs) {
  Map<String, int> counts = {};
  for (String log in logs) {
    List<String> parts = log.split(' ');
    if (parts.isNotEmpty) {
      String level = parts[0].replaceAll(':', '');
      counts[level] = (counts[level] ?? 0) + 1;
    }
  }
  List<String> result = counts.entries.map((e) => '${e.key}:${e.value}').toList();
  result.sort();
  return result;
}

@pragma('vm:entry-point')
void main() {
  assert(summarizeServerLogs(['INFO login', 'ERROR timeout', 'INFO logout']).toString() == '[ERROR:1, INFO:2]');
  assert(summarizeServerLogs([]).toString() == '[]');
  print('All tests passed!');
