@pragma('vm:entry-point')
String sortBarcodeDigits(String barcode) {
  var digits = barcode.split('').map((c) => int.parse(c)).toList();
  digits.sort((a, b) {
    bool aOdd = a % 2 != 0;
    bool bOdd = b % 2 != 0;
    if (aOdd && !bOdd) return -1;
    if (!aOdd && bOdd) return 1;
    if (aOdd) return a.compareTo(b);
    return b.compareTo(a);
  });
  return digits.map((d) => d.toString()).join('');
}

