bool isTidalRangeDivisibleByTen(List<int> readings) {
  if (readings.isEmpty) return true;
  int minVal = readings[0];
  int maxVal = readings[0];
  for (int r in readings) {
    if (r < minVal) minVal = r;
    if (r > maxVal) maxVal = r;
  }
  return (maxVal - minVal) % 10 == 0;
}

