List<int> processChessUndoLog(List<String> commands) {
  List<int> stack = [];
  for (String cmd in commands) {
    if (cmd == 'UNDO') {
      if (stack.isNotEmpty) stack.removeLast();
    } else if (cmd.length == 2) {
