List<int> highTideReadings(List<int> sortedReadings, int threshold) {
  int left = 0;
  int right = sortedReadings.length;
  while (left < right) {
    int mid = left + (right - left) ~/ 2;
    if (sortedReadings[mid] < threshold) {
      left = mid + 1;
    } else {
      right = mid;
    }
  }
  return sortedReadings.sublist(left);
}

