bool hasFullBucketCycle(int bucketCount, int stepSize) {
  if (bucketCount <= 1 || stepSize <= 0) {
    return false;
  }

  int a = bucketCount;
  int b = stepSize;

  while (b != 0) {
    int temp = a % b;
    a = b;
    b = temp;
  }

  return a == 1;
}

