int segmentLengthGcd(String row) {
  int gcd(int a, int b) {
    while (b != 0) {
      int t = b;
      b = a % b;
      a = t;
    }
    return a;
  }
  List<String> segments = row.split(' ').where((s) => s.isNotEmpty).toList();
  if (segments.isEmpty) return 0;
  List<int> lengths = segments.map((s) => s.length).toList();
  int result = lengths[0];
  for (int i = 1; i < lengths.length; i++) {
    result = gcd(result, lengths[i]);
  }
  return result;
}

