double topCorrectionFrequency(String word, List<String> candidates, Map<String, double> frequencies) {
  if (candidates.isEmpty) return 0.0;
  var sortedCandidates = List<String>.from(candidates);
  sortedCandidates.sort((a, b) {
    double scoreA = frequencies[a] ?? 0.0;
    double scoreB = frequencies[b] ?? 0.0;
