Set<int> occupiedWifiBins(List<int> signalStrengths) {
  int mask = 0;
  for (final s in signalStrengths) {
    int bin = s >= -50 ? 0 : s >= -60 ? 1 : s >= -70 ? 2 : 3;
    mask |= 1 << bin;
  }
  final result = <int>{};
  for (int i = 0; i < 4; i++) {
