@pragma('vm:entry-point')
int longestCloseFloorSequence(List<int> requests, int maxDifference) {
  int left = 0;
  int best = 0;

  for (int right = 0; right < requests.length; right++) {
    while (requests[right] - requests[left] > maxDifference) {
      left++;
    }
    int length = right - left + 1;
    if (length > best) {
      best = length;
    }
  }

  return best;
}

