@pragma('vm:entry-point')
List<String> checkPasswordRules(String password) {
  Set<String> check(int i, Set<String> s) => i == password.length ? s : check(i+1, s..addAll({
    if (password[i].contains(RegExp(r'[A-Z]'))) 'uppercase',
    if (password[i].contains(RegExp(r'[a-z]'))) 'lowercase',
    if (password[i].contains(RegExp(r'[0-9]'))) 'digit',
    if (password[i].contains(RegExp(r'[!@#$%^&*]'))) 'special',
  }));
  final satisfied = check(0, {});
  final violations = {'uppercase','lowercase','digit','special'}.difference(satisfied).toList();
  if (password.length < 8) violations.add('length');
  return violations;
}

