@pragma('vm:entry-point')
String diceRoundSummary(List<int> rolls) {
  List<int> kept = rolls.where((r) => r >= 4).toList();
  List<int> discarded = rolls.where((r) => r < 4).toList();
  String countStr(List<int> values, List<int> data) {
    return values.map((v) => '$v:${data.where((d) => d == v).length}').join(', ');
  }
  return 'Kept: ${countStr([4,5,6], kept)}; Discarded: ${countStr([1,2,3], discarded)}';
}

