  assert(diceRoundSummary([]) == "Kept: 4:0, 5:0, 6:0; Discarded: 1:0, 2:0, 3:0");
  assert(diceRoundSummary([4]) == "Kept: 4:1, 5:0, 6:0; Discarded: 1:0, 2:0, 3:0");
  assert(diceRoundSummary([4,4,6,5]) == "Kept: 4:2, 5:1, 6:1; Discarded: 1:0, 2:0, 3:0");
