String checkPasswordRepeatRun(String password) {
  int left = 0;
  while (left < password.length) {
    int right = left + 1;
    while (right < password.length && password[right] == password[left]) {
      right++;
    }
    if (right - left > 2) {
      return "invalid: repeat '${password[left]}' x${right - left}";
