List<String> qrModuleRows(int packedModules, int size) {
  List<String> rows = [];
  String current = '';

  for (int i = 0; i < size * size; i++) {
    int bit = (packedModules >> i) & 1;
    current += bit == 1 ? '#' : '.';

    if ((i + 1) % size == 0) {
      rows.add(current);
      current = '';
    }
  }

  return rows;
}

