bool isValidSnakePath(List<String> rows) {
  int prevCol = -1;
  for (String row in rows) {
    int count = 0;
    int col = -1;
    for (int i = 0; i < row.length; i++) {
      if (row[i] == 'X') {
        count++;
        col = i;
      }
    }
    if (count != 1) return false;
    if (prevCol != -1 && (col - prevCol).abs() > 1) return false;
    prevCol = col;
  }
  return true;
}

