Set<int> oddVoteCandidates(List<int> votes) {
  int xorAccumulator = 0;
  for (int vote in votes) {
    xorAccumulator ^= vote;
  }
  Set<int> result = {};
  int position = 0;
  while (xorAccumulator != 0) {
    if ((xorAccumulator & 1) == 1) {
      result.add(position);
    }
    xorAccumulator >>= 1;
    position++;
  }
  return result;
}

