@pragma('vm:entry-point')
int totalNickelRoundingAdjustment(List<int> cents) {
  if (cents.isEmpty) {
    return 0;
  }

  int remainder = cents.last % 5;
  int adjustment = remainder <= 2 ? -remainder : 5 - remainder;

  return adjustment +
      totalNickelRoundingAdjustment(cents.sublist(0, cents.length - 1));
}

