@pragma('vm:entry-point')
bool hasSubarrayWithBrightnessSum(List<int> pixels, int targetSum) {
  int left = 0;
  int currentSum = 0;
  for (int right = 0; right < pixels.length; right++) {
    currentSum += pixels[right];
    while (currentSum > targetSum && left <= right) {
      currentSum -= pixels[left];
      left++;
    }
    if (currentSum == targetSum) {
      return true;
    }
  }
  return false;
}

@pragma('vm:entry-point')
void main() {
  assert(hasSubarrayWithBrightnessSum([50, 100, 150, 200], 250) == true);
  assert(hasSubarrayWithBrightnessSum([10, 20, 30], 100) == false);
  assert(hasSubarrayWithBrightnessSum([255], 255) == true);
  print('All tests passed!');
}

