@pragma('vm:entry-point')
List<String> reorderUniqueChessSquares(List<String> squares) {
  Set<String> unique = {};
  for (var s in squares) {
    if (s.length == 2) {
      String file = s[0];
      String rank = s[1];
      if (file.codeUnitAt(0) >= 'a'.codeUnitAt(0) && file.codeUnitAt(0) <= 'h'.codeUnitAt(0) &&
          rank.codeUnitAt(0) >= '1'.codeUnitAt(0) && rank.codeUnitAt(0) <= '8'.codeUnitAt(0)) {
        unique.add(s);
      }
    }
  }
  List<String> valid = unique.toList();
  valid.sort((a, b) {
    int rankA = int.parse(a[1]);
    int rankB = int.parse(b[1]);
    if (rankA != rankB) return rankA.compareTo(rankB);
    return a[0].compareTo(b[0]);
  });
  return valid;
}

@pragma('vm:entry-point')
void main() {
  assert(reorderUniqueChessSquares(['a1','a1']).length == 1);
  assert(reorderUniqueChessSquares([]).length == 0);
  assert(reorderUniqueChessSquares(['i1']).length == 0);
  print('All tests passed!');
}

tests:
void main() {
  final candidate = reorderUniqueChessSquares;

  expect(candidate([]), []);
  expect(candidate(['a1']), ['a1']);
  expect(candidate(['a1','a1']), ['a1']);
  expect(candidate(['h8','a1']), ['a1','h8']);
  expect(candidate(['c3','a1','b2']), ['a1','b2','c3']);
  expect(candidate(['a9','b2','i1']), ['b2']);
  expect(candidate(['h8','h8','a1','b1']), ['a1','b1','h8']);
  expect(candidate(['d4','d4','d5','d3']), ['d3','d4','d5']);
}

